class MainActivity : ComponentActivity() {
    companion object { init { System.loadLibrary("kabootarbook") } }
    private external fun nativeInit(path: String): String
    private external fun nativeSavePigeon(json: String): String
    private external fun nativeSetPigeonStatus(id: String, reason: String): String
    private external fun nativeDeletePigeon(id: String): String
    private external fun nativeStartFlight(json: String): String
    private external fun nativeStopFlight(end: String): String
    private external fun nativeReturnPigeon(id: String, returnedAt: String): String
    private external fun nativeAddFlight(json: String): String
    private external fun nativeDeleteFlight(id: String): String
    private external fun nativeSaveSettings(json: String): String
    private external fun nativeImportLegacy(json: String): String
    private external fun nativeLoad(): String
    private val importBackup = registerForActivityResult(ActivityResultContracts.OpenDocument()) { uri -> if(uri!=null){val raw=contentResolver.openInputStream(uri)?.bufferedReader()?.use{it.readText()};if(raw!=null){val result=nativeImportLegacy(raw);if(!result.contains("\"error\""))recreate()}} }
    private val exportJson = registerForActivityResult(ActivityResultContracts.CreateDocument("application/json")) { uri -> if(uri!=null)contentResolver.openOutputStream(uri)?.use{it.write(nativeLoad().toByteArray())} }
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); window.statusBarColor = android.graphics.Color.rgb(244,241,232); window.navigationBarColor=android.graphics.Color.rgb(244,241,232); window.decorView.systemUiVisibility=android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR or android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR
        var data = nativeInit(getDatabasePath("kabootarbook.db").absolutePath)
        val initialData=data
        setContent { KabootarBookApp(initialData, { importBackup.launch(arrayOf("application/json")) }, ::nativeSavePigeon, ::nativeSetPigeonStatus, ::nativeDeletePigeon, ::nativeStartFlight, ::nativeStopFlight, ::nativeReturnPigeon, ::nativeAddFlight, ::nativeDeleteFlight, ::nativeSaveSettings) }
    }
}

private val darkGreen=androidx.compose.ui.graphics.Color(0xFF234A39)
private val lightColors=lightColorScheme(primary=androidx.compose.ui.graphics.Color(0xFF234A39),background=androidx.compose.ui.graphics.Color(0xFFF4F1E8),surface=androidx.compose.ui.graphics.Color(0xFFFFFDF8))
private val darkColors=darkColorScheme(primary=androidx.compose.ui.graphics.Color(0xFF9FBE9C),background=androidx.compose.ui.graphics.Color(0xFF161C18),surface=androidx.compose.ui.graphics.Color(0xFF202822))
@Composable private fun KabootarTheme(dark:Boolean,content:@Composable ()->Unit){MaterialTheme(colorScheme=if(dark)darkColors else lightColors,content=content)}
@Composable private fun KabootarBookApp(initial:String,launchImport:()->Unit,savePigeon:(String)->String,status:(String,String)->String,deletePigeon:(String)->String,startFlight:(String)->String,stopFlight:(String)->String,returnPigeon:(String,String)->String,addFlight:(String)->String,deleteFlight:(String)->String,saveSettings:(String)->String){
    var json by remember { mutableStateOf(runCatching { JSONObject(initial) }.getOrElse { JSONObject() }) };var routeStack by remember{mutableStateOf(listOf("Today"))};val route=routeStack.last();val page=if(route.startsWith("PigeonProfile:"))"PigeonProfile" else route;var dialog by remember{mutableStateOf("")};var selectedId by remember{mutableStateOf("")};var msg by remember{mutableStateOf("")};var pendingDeleteFlight by remember{mutableStateOf("")};var pendingReturnPigeon by remember{mutableStateOf("")}
    fun navigate(route:String){if(routeStack.lastOrNull()!=route)routeStack=routeStack+route}
    fun goBack(){if(dialog.isNotEmpty())dialog="" else if(routeStack.size>1)routeStack=routeStack.dropLast(1)}
    fun refresh(raw:String){val next=runCatching{JSONObject(raw)}.getOrElse{JSONObject().put("error",it.message?:"Error")};if(next.has("error")){msg=next.optString("error")}else{json=next;msg=""}}
    val pigeons=json.optJSONArray("pigeons")?:JSONArray();val flights=json.optJSONArray("flights")?:JSONArray();val active=json.optJSONObject("active");val isDark=json.optJSONObject("settings")?.optString("theme")=="dark";var clock by remember{mutableLongStateOf(System.currentTimeMillis())};LaunchedEffect(active?.optString("startedAt")){while(active!=null){clock=System.currentTimeMillis();delay(1000)}}
    BackHandler(enabled=pendingDeleteFlight.isNotEmpty()||pendingReturnPigeon.isNotEmpty()||dialog.isNotEmpty()||routeStack.size>1){if(pendingDeleteFlight.isNotEmpty())pendingDeleteFlight="" else if(pendingReturnPigeon.isNotEmpty())pendingReturnPigeon="" else goBack()}
    KabootarTheme(isDark){Scaffold(bottomBar={NavigationBar{listOf("Today","Pigeons","Flights","Settings").forEach{NavigationBarItem(selected=page==it,onClick={routeStack=if(it=="Today")listOf("Today") else listOf("Today",it)},icon={Text(when(it){"Today"->"◷";"Pigeons"->"♧";"Flights"->"↗";else->"⚙"})},label={Text(it)})}}}){pad->
        Column(Modifier.fillMaxSize().padding(pad).statusBarsPadding().padding(horizontal=18.dp, vertical=10.dp)){
            Text("KABOOTARBOOK  ·  LOFT JOURNAL",style=MaterialTheme.typography.labelSmall,color=darkGreen,fontWeight=FontWeight.Bold);Spacer(Modifier.height(5.dp));Text(if(page=="PigeonProfile")"Pigeon profile" else page,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Spacer(Modifier.height(12.dp))
            if(msg.isNotBlank())Text(msg,color=MaterialTheme.colorScheme.error)
            when(page){
                "Today"->{if(active!=null){Text("FLIGHT IN PROGRESS",color=darkGreen,fontWeight=FontWeight.Bold);Text("Elapsed ${activeDuration(active,clock)}");val activeIds=active.optJSONArray("pigeonIds")?:JSONArray();for(i in 0 until activeIds.length()){val birdId=activeIds.optString(i);val bird=(0 until pigeons.length()).mapNotNull{pigeons.optJSONObject(it)}.firstOrNull{it.optString("id")==birdId};if(bird!=null){val landed=active.optJSONObject("pigeonReturnedAt")?.optString(birdId).orEmpty();Row(verticalAlignment=Alignment.CenterVertically){Text("${bird.optString("name").ifBlank{bird.optString("ring")}} · ${if(landed.isEmpty())"Flying" else "Returned ${activeDuration(active,clock)}"}",Modifier.weight(1f));if(landed.isEmpty())TextButton(onClick={pendingReturnPigeon=birdId}){Text("Record return")}else Text(flightDurationBetween(active.optString("startedAt"),landed))};TextButton(onClick={navigate("PigeonProfile:$birdId")}){Text("Open pigeon profile")}}}}else Button(onClick={if(pigeons.length()==0)dialog="add" else {selectedId="";dialog="start"}}){Text("Start a flight")};Spacer(Modifier.height(12.dp));Text("${pigeons.length()} pigeons · ${flights.length()} completed flights");TextButton(onClick={navigate("Pigeons")}){Text("Open loft")}}
                "PigeonProfile"->{val profileId=route.substringAfter(":","");val p=(0 until pigeons.length()).mapNotNull{pigeons.optJSONObject(it)}.firstOrNull{it.optString("id")==profileId};if(p==null)Text("Pigeon record not found")else PigeonProfile(p,flights,active){action->if(action=="return")pendingReturnPigeon=profileId else {dialog="edit";selectedId=profileId}}}
                "Pigeons"->{Row(verticalAlignment=Alignment.CenterVertically){Text("Active loft and retired birds",Modifier.weight(1f));Button(onClick={dialog="add"}){Text("＋ Add")}};LazyColumn{items((0 until pigeons.length()).filter{pigeons.optJSONObject(it)?.optBoolean("archived",false)==false}){i->val p=pigeons.getJSONObject(i);PigeonRow(p,flights,{navigate("PigeonProfile:${p.optString("id")}")},{dialog="edit";selectedId=p.optString("id")},{selectedId=p.optString("id");dialog=if(p.optBoolean("archived"))"restore" else "retire"},{refresh(deletePigeon(p.optString("id")))})};if((0 until pigeons.length()).any{pigeons.optJSONObject(it)?.optBoolean("archived",false)==true})item{Text("ARCHIVE",style=MaterialTheme.typography.titleMedium,color=darkGreen);Spacer(Modifier.height(5.dp))};items((0 until pigeons.length()).filter{pigeons.optJSONObject(it)?.optBoolean("archived",false)==true}){i->val p=pigeons.getJSONObject(i);PigeonRow(p,flights,{navigate("PigeonProfile:${p.optString("id")}")},{dialog="edit";selectedId=p.optString("id")},{selectedId=p.optString("id");dialog="restore"},{refresh(deletePigeon(p.optString("id")))})}}
                "Flights"->{Row(verticalAlignment=Alignment.CenterVertically){Text("Recorded release and return sessions",Modifier.weight(1f));TextButton(onClick={dialog="pastflight"}){Text("＋ Add")}};LazyColumn{items((0 until flights.length()).reversed()){i->val f=flights.getJSONObject(i);Card(Modifier.fillMaxWidth().padding(vertical=5.dp)){Column(Modifier.padding(14.dp)){Text("${birdNames(f,pigeons)} · ${flightDuration(f)}",fontWeight=FontWeight.Bold);Text("${f.optString("startedAt")} → ${f.optString("endedAt")}");TextButton(onClick={pendingDeleteFlight=f.optString("id")}){Text("Delete session")}}}}}}
                "Settings"->{val dark=isDark;Text("Preferences are saved on this device.");Row(verticalAlignment=Alignment.CenterVertically){Text("Dark appearance",Modifier.weight(1f));Switch(dark,{val s=json.optJSONObject("settings")?:JSONObject();s.put("theme",if(it)"dark" else "light");refresh(saveSettings(s.toString()))})};TextButton(onClick={navigate("Pigeons")}){Text("Manage pigeon archive")};Row{TextButton(onClick={exportJson.launch("kabootarbook-backup.json")}){Text("Export full JSON backup")};TextButton(onClick={launchImport}){Text("Import JSON backup")}};Text("Full JSON backup includes pigeons, completed and active flights, and preferences.",style=MaterialTheme.typography.bodySmall)}
            }
        }
    }
    }
    if(pendingReturnPigeon.isNotEmpty()){val bird=(0 until pigeons.length()).mapNotNull{pigeons.optJSONObject(it)}.firstOrNull{it.optString("id")==pendingReturnPigeon};AlertDialog(onDismissRequest={pendingReturnPigeon=""},title={Text("Record pigeon return?")},text={Text("${bird?.optString("name").orEmpty()} · ${bird?.optString("ring").orEmpty()} will be marked as returned now. Other pigeons remain in flight.")},confirmButton={TextButton(onClick={val id=pendingReturnPigeon;pendingReturnPigeon="";refresh(returnPigeon(id,Instant.now().toString()));pendingReturnPigeon=""}){Text("Record return")}},dismissButton={TextButton(onClick={pendingReturnPigeon=""}){Text("Cancel")}})}
    if(pendingDeleteFlight.isNotEmpty())AlertDialog(onDismissRequest={pendingDeleteFlight=""},title={Text("Delete this flight?")},text={Text("This removes the recorded session and its history.")},confirmButton={TextButton(onClick={val target=pendingDeleteFlight;pendingDeleteFlight="";refresh(deleteFlight(target))}){Text("Delete")}},dismissButton={TextButton(onClick={pendingDeleteFlight=""}){Text("Cancel")}})
    if(dialog.isNotEmpty())AlertDialog(onDismissRequest={dialog=""},title={Text(when(dialog){"add"->"Add pigeon";"edit"->"Edit pigeon";"retire"->"Move to archive";"restore"->"Restore pigeon";"start"->"Start flight";"pastflight"->"Add flight";else->"Pigeon details"})},text={when(dialog){"add","edit"->PigeonEditor(json.optJSONArray("pigeons")?:JSONArray(),selectedId){p->refresh(savePigeon(p.toString()));if(!p.has("error"))dialog=""};"retire"->Column{Text("Choose why this bird is leaving the active loft. Flight history will be kept.");TextButton(onClick={refresh(status(selectedId,"sold"));dialog=""}){Text("Sold")};TextButton(onClick={refresh(status(selectedId,"died"));dialog=""}){Text("Died")};TextButton(onClick={refresh(status(selectedId,"deleted"));dialog=""}){Text("Deleted")}};"restore"->Text("Return this pigeon to the active loft? Existing flights stay linked.");"start","pastflight"->FlightEditor(pigeons,active,dialog=="start"){f->val result=if(dialog=="start")startFlight(f.toString()) else addFlight(f.toString());refresh(result);if(!result.contains("\"error\""))dialog=""};else->Text("")}},confirmButton={TextButton(onClick={when(dialog){"restore"->{refresh(status(selectedId,""));dialog=""};else->dialog=""}}){Text(if(dialog=="restore")"Restore" else "Close")}},dismissButton={TextButton(onClick={dialog=""}){Text("Cancel")}})
}

@Composable private fun PigeonProfile(p:JSONObject,flights:JSONArray,active:JSONObject?,onAction:(String)->Unit){val rows=(0 until flights.length()).mapNotNull{flights.optJSONObject(it)}.filter{f->val ids=f.optJSONArray("pigeonIds")?:JSONArray();(0 until ids.length()).any{ids.optString(it)==p.optString("id")}}.sortedByDescending{it.optString("startedAt")};val seconds=rows.mapNotNull{f->val start=runCatching{Instant.parse(f.optString("startedAt"))}.getOrNull()?:return@mapNotNull null;val end=runCatching{Instant.parse(f.optJSONObject("pigeonReturnedAt")?.optString(p.optString("id"))?:f.optString("endedAt"))}.getOrNull()?:return@mapNotNull null;Duration.between(start,end).seconds.takeIf{it>=0}};Column{Text("Ring ${p.optString("ring")}",style=MaterialTheme.typography.titleLarge);Text("${p.optString("breed")} · ${p.optString("colour")}");Text("${p.optString("sex")} · hatched ${p.optString("hatchDate")}");Text("Loft: ${p.optString("loft")}");Text(p.optString("notes"));if(p.optBoolean("archived"))Text("${p.optString("archiveReason")} · archived");val activeIds=active?.optJSONArray("pigeonIds")?:JSONArray();if((0 until activeIds.length()).any{activeIds.optString(it)==p.optString("id")}){val returned=active?.optJSONObject("pigeonReturnedAt")?.optString(p.optString("id")).orEmpty();Text(if(returned.isEmpty())"Current session · flying" else "Current session · returned ${flightDurationBetween(active?.optString("startedAt").orEmpty(),returned)}");if(returned.isEmpty())Button(onClick={onAction("return")}){Text("Record return")}};Spacer(Modifier.height(10.dp));Text("${rows.size} flights · ${seconds.sum()/3600} hr ${seconds.sum()%3600/60} min total · ${if(seconds.isEmpty())"—" else "${seconds.maxOrNull()!!/60} min best"}",fontWeight=FontWeight.Bold);TextButton(onClick={onAction("edit")}){Text("Edit profile")};Text("FLIGHT HISTORY",style=MaterialTheme.typography.titleMedium);if(rows.isEmpty())Text("No flights recorded yet")else rows.forEach{f->val returned=f.optJSONObject("pigeonReturnedAt")?.optString(p.optString("id"));val end=returned?.takeIf{it.isNotBlank()}?:f.optString("endedAt");Card(Modifier.fillMaxWidth().padding(vertical=4.dp)){Column(Modifier.padding(12.dp)){Text("${flightDurationBetween(f.optString("startedAt"),end)} · ${f.optString("startedAt")}",fontWeight=FontWeight.Bold);if(returned.isNullOrBlank())Text("Session return time (legacy group record)",style=MaterialTheme.typography.bodySmall);Text(f.optString("notes"))}}}}}
@Composable private fun PigeonRow(p:JSONObject,flights:JSONArray,onOpen:()->Unit,onEdit:()->Unit,onRetire:()->Unit,onDelete:()->Unit){val count=(0 until flights.length()).count{flights.optJSONObject(it)?.optJSONArray("pigeonIds")?.let{ids->(0 until ids.length()).any{j->ids.optString(j)==p.optString("id")}}==true};Card(Modifier.fillMaxWidth().padding(vertical=5.dp)){Column(Modifier.padding(13.dp)){TextButton(onClick=onOpen){Text(p.optString("name").ifBlank{p.optString("ring")},fontWeight=FontWeight.Bold)};Text("Ring ${p.optString("ring")} · $count flights");if(p.optBoolean("archived"))Text("${p.optString("archiveReason").replaceFirstChar{it.uppercase()}} · archived");Row{TextButton(onClick=onEdit){Text("Edit")};TextButton(onClick=onRetire){Text(if(p.optBoolean("archived"))"Restore" else "Archive")};if(p.optBoolean("archived"))TextButton(onClick=onDelete){Text("Delete")}}}}}
@Composable private fun PigeonEditor(pigeons:JSONArray,id:String,onSave:(JSONObject)->Unit){val old=(0 until pigeons.length()).mapNotNull{pigeons.optJSONObject(it)}.firstOrNull{it.optString("id")==id};var ring by remember(id){mutableStateOf(old?.optString("ring")?:"")};var name by remember(id){mutableStateOf(old?.optString("name")?:"")};var breed by remember(id){mutableStateOf(old?.optString("breed")?:"")};var colour by remember(id){mutableStateOf(old?.optString("colour")?:"")};var loft by remember(id){mutableStateOf(old?.optString("loft")?:"")};var sex by remember(id){mutableStateOf(old?.optString("sex")?:"")};var hatchDate by remember(id){mutableStateOf(old?.optString("hatchDate")?:"")};var notes by remember(id){mutableStateOf(old?.optString("notes")?:"")};Column{OutlinedTextField(ring,{ring=it},label={Text("Ring number")},singleLine=true);OutlinedTextField(name,{name=it},label={Text("Name")},singleLine=true);OutlinedTextField(breed,{breed=it},label={Text("Breed")},singleLine=true);OutlinedTextField(colour,{colour=it},label={Text("Colour")},singleLine=true);OutlinedTextField(loft,{loft=it},label={Text("Loft")},singleLine=true);OutlinedTextField(sex,{sex=it},label={Text("Sex")},singleLine=true);OutlinedTextField(hatchDate,{hatchDate=it},label={Text("Hatch date")},singleLine=true);OutlinedTextField(notes,{notes=it},label={Text("Notes")});Button(onClick={val p=old?:JSONObject();p.put("id",p.optString("id").ifBlank{UUID.randomUUID().toString()});p.put("ring",ring.trim());p.put("name",name.trim());p.put("breed",breed.trim());p.put("colour",colour.trim());p.put("loft",loft.trim());p.put("sex",sex.trim());p.put("hatchDate",hatchDate.trim());p.put("notes",notes.trim());p.put("custom",p.optJSONObject("custom")?:JSONObject());p.put("archived",p.optBoolean("archived"));onSave(p)}){Text("Save pigeon")}}}
private fun birdNames(f:JSONObject,pigeons:JSONArray):String{val ids=f.optJSONArray("pigeonIds")?:JSONArray();return (0 until ids.length()).mapNotNull{ id->(0 until pigeons.length()).mapNotNull{pigeons.optJSONObject(it)}.firstOrNull{it.optString("id")==ids.optString(id)}?.let{it.optString("name").ifBlank{it.optString("ring")}}}.joinToString().ifBlank{"No pigeon linked"}}
private fun flightDuration(f:JSONObject):String=runCatching{Duration.between(Instant.parse(f.getString("startedAt")),Instant.parse(f.getString("endedAt"))).toMinutes().let{"${it/60} hr ${it%60} min"}}.getOrDefault("—")

@Composable private fun FlightEditor(pigeons:JSONArray,active:JSONObject?,startNow:Boolean,onSave:(JSONObject)->Unit){
    val selected=remember { mutableStateListOf<String>().also { list -> if(active!=null){val old=active.optJSONArray("pigeonIds")?:JSONArray();for(i in 0 until old.length())list.add(old.optString(i))} } }
    var notes by remember{mutableStateOf("")}
    Column {
        Text("Select pigeons for this shared session")
        for(i in 0 until pigeons.length()) { val p=pigeons.optJSONObject(i)?:continue;if(p.optBoolean("archived"))continue;val id=p.optString("id");Row(verticalAlignment=Alignment.CenterVertically){Checkbox(checked=id in selected,onCheckedChange={if(it)selected.add(id)else selected.remove(id)});Text("${p.optString("name").ifBlank{p.optString("ring")}} · ${p.optString("ring")}")}}
        OutlinedTextField(notes,{notes=it},label={Text("Notes")},singleLine=true)
        Button(onClick={val now=Instant.now().toString();val began=active?.optString("startedAt")?:now;val end=if(startNow)"" else now;val ids=JSONArray().also{a->selected.forEach{a.put(it)}};val obj=JSONObject().put("id",active?.optString("id")?:UUID.randomUUID().toString()).put("pigeonIds",ids).put("startedAt",began).put("endedAt",end).put("notes",notes).put("conditions","").put("location","").put("custom",JSONObject());if(selected.isNotEmpty())onSave(obj)} ,enabled=selected.isNotEmpty()) { Text(if(startNow)"Start now" else "Save return now") }
    }
}

private fun activeDuration(f:JSONObject,now:Long):String=runCatching{val start=Instant.parse(f.getString("startedAt")).toEpochMilli();val total=((now-start).coerceAtLeast(0))/60000;"${total/60} hr ${total%60} min"}.getOrDefault("—")

private fun flightDurationBetween(start:String,end:String):String=runCatching{Duration.between(Instant.parse(start),Instant.parse(end)).toMinutes().let{"${it/60} hr ${it%60} min"}}.getOrDefault("—")
